const DATASTORE_KEY = "contador_casos_criticos";
const dataStore = $getWorkflowStaticData('global');
if (!dataStore[DATASTORE_KEY]) dataStore[DATASTORE_KEY] = 0;
dataStore[DATASTORE_KEY]++;
const contador = dataStore[DATASTORE_KEY];

let idCaso = "CRIT-" + String(contador).padStart(4, "0");
let protocoloBV = "";

const mensagem = $json.message.text;
const partes = mensagem.split("\n");
const match = mensagem.match(/(CRIT-\d+)\s+BV\s+(\d+)/i);
if (match) { idCaso = match[1]; protocoloBV = match[2]; }

function limparTexto(texto, regex) {
  if (!texto) return "";
  return texto.replace(regex, "").trim();
}

const protocolo = limparTexto(partes[0], /Protocolo\s*N1\s*:/i);
const cliente   = limparTexto(partes[1], /Código\s*Cliente\s*:/i);
const assunto   = limparTexto(partes[2], /Assunto\s*Caso\s*:/i);
const descricao = limparTexto(partes[3], /Detalhamento\s*Caso\s*:/i);

const timestamp = $json.message.date;
const dataObj   = new Date(timestamp * 1000);
const data      = dataObj.toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" });
const hora      = dataObj.toLocaleTimeString("pt-BR", { timeZone: "America/Sao_Paulo" });

// Nome completo (first_name + last_name) para match com MAPA_EMAILS
const firstName  = ($json.message.from.first_name || '').trim();
const lastName   = ($json.message.from.last_name  || '').trim();
const responsavel = [firstName, lastName].filter(Boolean).join(' ');

return [{ json: {
  ID_Caso: idCaso,
  Protocolo_BV: protocoloBV,
  Data_Abertura: data,
  Hora_Abertura: hora,
  Protocolo: protocolo,
  Codigo_Cliente: cliente,
  Assunto: assunto,
  Descricao: descricao,
  Responsavel: responsavel,
  Status: "Aberto",
  Dias_Aberto: 0,
  Timestamp_Abertura: timestamp
} }];

const MAPA_EMAILS = {
  'Rodrigo Bertolini': 'rodrigo.bertolini@fazcapital.com.br',
  'Lucas Boeira':      'lucas.boeira@fazcapital.com.br',
  'Allini Pianca':     'allini.pianca@fazcapital.com.br',
  'Athos Baruk':       'athos.baruk@fazcapital.com.br',
  'Fabio Borges':      'fabio.borges@fazcapital.com.br'
};

function findEmail(nome) {
  if (!nome) return '';
  if (MAPA_EMAILS[nome]) return MAPA_EMAILS[nome];
  const nomeLower = nome.toLowerCase();
  for (const [chave, email] of Object.entries(MAPA_EMAILS)) {
    const chaveLower = chave.toLowerCase();
    if (chaveLower.includes(nomeLower)) return email;
    if (chave.split(' ').some(p => p.toLowerCase() === nomeLower)) return email;
  }
  // Fallback: busca pelo primeiro nome
  const primeiroInput = nomeLower.split(' ')[0];
  if (primeiroInput) {
    for (const [chave, email] of Object.entries(MAPA_EMAILS)) {
      if (chave.split(' ')[0].toLowerCase() === primeiroInput) return email;
    }
  }
  return '';
}

const responsavelRaw = (
  $json['Responsável'] || $json['Responsavel'] || ''
).split('|')[0].trim();

// Estrategia 1: extrai email diretamente do campo
// (formato Telegram: first_name=email, last_name=nome)
const emailNosCampo = (responsavelRaw.match(/([\w.+-]+@[\w.-]+\.[\w]+)/) || [])[1] || '';

// Estrategia 2 (fallback): lookup pelo nome sem o email
const nomeSemEmail = responsavelRaw.replace(/[\w.+-]+@[\w.-]+\.[\w]+/g, '').trim();

const emailDest = emailNosCampo || findEmail(nomeSemEmail);

if (!emailDest) {
  console.log('AVISO: email nao encontrado. Campo Responsavel:', JSON.stringify(responsavelRaw));
  return [];
}

const idCaso    = $json['ID Caso']         || $json['ID_Caso']        || '';
const status    = $json['Status']                                      || 'Aberto';
const protocolo = $json['Protocolo N1']    || $json['Protocolo']      || '';
const cliente   = $json['Código Cliente']  || $json['Codigo_Cliente'] || '';
const assunto   = $json['Assunto']                                     || '';
const descricao = $json['Descrição']       || $json['Descricao']      || '';

const corpo =
  'Prezado(a),\n\n' +
  '🚨 Caso Crítico registrado! \n\n' +
  'As tratativas e atualizações deste caso serão realizadas por este e-mail.\n\n' +
  'Caso possua anexos ou novas informações, envie por este e-mail para registrar e complementar o caso.\n\n\n\n' +
  'ID: '       + idCaso    + '\n' +
  'Status: '   + status    + '\n\n' +
  '📌 Protocolo: ' + protocolo + '\n' +
  '👤 Cliente: '   + cliente   + '\n\n' +
  '📝 Assunto Caso: ' + assunto  + '\n\n' +
  '📄 Descrição: ' + descricao + '\n\n\n\n\nAtenciosamente,\n\n';

return [{
  json: {
    ...$json,
    id_caso_ref: idCaso,
    email_destinatario: emailDest,
    draft_body: {
      subject: '[SUBIR BV] ' + idCaso + ' | Cliente ' + cliente + ' | ' + assunto,
      body: { contentType: 'Text', content: corpo },
      toRecipients: [{ emailAddress: { address: emailDest } }],
      ccRecipients: [{ emailAddress: { address: 'lucas.boeira@fazcapital.com.br' } }]
    }
  }
}];

// Captura o internetMessageId do draft ANTES de enviar.
// internetMessageId é o Message-ID RFC 2822 — estável e único para cada e-mail.
// Após ENVIAR_EMAIL (202 No Content), $json fica vazio, por isso salvamos aqui.
const messageId         = $json.id                || '';
const internetMessageId = $json.internetMessageId || '';
const idCaso            = $('PREPARAR_EMAIL').item.json.id_caso_ref || '';

if (!messageId) {
  throw new Error('CRIAR_EMAIL nao retornou o ID da mensagem. Verifique as credenciais do Outlook.');
}

if (!internetMessageId) {
  console.log('AVISO: internetMessageId nao encontrado na resposta do Graph API.');
}

console.log('Internet Message ID capturado:', internetMessageId);
console.log('ID Caso ref:', idCaso);

return [{ json: {
  message_id: messageId,
  thread_id:  internetMessageId,
  id_caso:    idCaso
} }];

function addBusinessDays(days) {
  const date = new Date();
  let added = 0;
  while (added < days) {
    date.setDate(date.getDate() + 1);
    const dow = date.getDay();
    if (dow !== 0 && dow !== 6) added++;
  }
  return date;
}

const prep     = $('PREPARAR_EMAIL').item.json;
const idCaso   = prep.id_caso_ref || '';
const cliente  = prep['Código Cliente'] || prep['Codigo_Cliente'] || '';
const emailDest = prep.email_destinatario || '';

const prazoDate = addBusinessDays(2);
const pad = n => String(n).padStart(2, '0');
const prazoISO = prazoDate.getFullYear() + '-' + pad(prazoDate.getMonth() + 1) + '-' + pad(prazoDate.getDate());

console.log('Evento cobranca D+2 para', idCaso, ':', prazoISO);

const attendees = [{ emailAddress: { address: 'lucas.boeira@fazcapital.com.br' }, type: 'required' }];

return [{
  json: {
    id_caso: idCaso,
    event_cobranca: {
      subject: '⏰ Cobrança — ' + idCaso + ' | Cliente ' + cliente,
      start: { dateTime: prazoISO + 'T09:00:00', timeZone: 'America/Sao_Paulo' },
      end:   { dateTime: prazoISO + 'T09:30:00', timeZone: 'America/Sao_Paulo' },
      body: {
        contentType: 'Text',
        content: 'Prazo de cobrança (D+2 úteis).\n\n⚠️ Se o caso não foi resolvido, escale para a área de líderes de atendimento (BDO).'
      },
      attendees: attendees,
      isReminderOn: true,
      reminderMinutesBeforeStart: 60
    }
  }
}];

